usage() { echo "usage: $0 --env <stage|prod> [--apply]"; exit 1; }

while [[ $# -gt 0 ]]; do
  case "$1" in
    --env) ENV="$2"; shift 2 ;;
    --apply) APPLY=1; shift ;;
    *) usage ;;
  esac
done

log() { printf '%s [%s] %s\n' "$(date -Is)" "$1" "${*:2}" >&2; }

log INFO "деплой версии $VERSION"
log ERROR "миграция упала"; exit 1

run() { if [[ "${APPLY:-0}" == 1 ]]; then "$@"; else echo "[dry-run] $*"; fi; }

run docker rm -f old-container
run aws s3 rm "s3://bucket/$KEY"
